-- Staging-only. All fixture identities, outlets, sessions and financial evidence roll back.
do $$
declare outlet uuid:=gen_random_uuid();emp uuid:=gen_random_uuid();other_emp uuid:=gen_random_uuid();own uuid;role_id uuid;
 tok text:=encode(extensions.gen_random_bytes(32),'hex');other_tok text:=encode(extensions.gen_random_bytes(32),'hex');
 day date:=timezone('Asia/Kuala_Lumpur',now())::date;first uuid;second uuid;third uuid;v jsonb;before_cancel jsonb;denied boolean;
begin
 select e.auth_user_id into own from public.employees e join public.roles r on r.id=e.role_id where lower(r.name)='owner' and e.is_active and e.auth_user_id is not null limit 1;
 select e.role_id into role_id from public.employees e join public.crew_access a on a.employee_id=e.id where e.employee_code like 'QA-%' and public.crew_cash_can_perform_checkout(e.id,a.primary_outlet_id) limit 1;
 assert own is not null,'Verified QA owner required';
 perform set_config('request.jwt.claim.sub',own::text,true);
 insert into public.outlets(id,name) values(outlet,'QA Cash restart '||outlet::text);
 insert into public.employees(id,full_name,employee_code,role_id,workplace,position) values(emp,'QA Restart Crew','QA-RST-'||emp::text,role_id,'QA Cash restart '||outlet::text,'Cashier'),(other_emp,'QA Other Crew','QA-RST-'||other_emp::text,role_id,'QA Cash restart '||outlet::text,'Cashier');
 insert into public.crew_access(employee_id,mobile_number,passcode_hash,primary_outlet_id) values(emp,'qa-'||emp::text,'rollback-only',outlet),(other_emp,'qa-'||other_emp::text,'rollback-only',outlet);
 insert into public.crew_sessions(employee_id,token_hash,expires_at) values(emp,encode(extensions.digest(tok,'sha256'),'hex'),now()+interval '1 hour'),(other_emp,encode(extensions.digest(other_tok,'sha256'),'hex'),now()+interval '1 hour');
 assert public.crew_cash_can_perform_checkout(emp,outlet),'Real Crew permission/outlet authority';
 perform set_config('request.jwt.claim.sub',own::text,true);
 perform public.crew_cash_save_settings(outlet,'{"variance_tolerance":0,"require_manager_review_over_tolerance":true}');
 perform public.crew_cash_save_settings(outlet,jsonb_build_object('floating_cash',300,'effective_date',day-1,'reason','Rollback-only restart verification'));
 perform set_config('request.jwt.claim.sub','',true);
 v:=public.crew_cash_save_checkout(tok,'draft','{"denomination_counts":{"100":7,"10":4,"1":6},"pos_expected_cash":700}');first:=(v#>>'{checkout,id}')::uuid;
 perform public.crew_cash_save_checkout(tok,'reconcile',jsonb_build_object('checkout_id',first));
 perform public.crew_cash_save_checkout(tok,'submit',jsonb_build_object('checkout_id',first,'variance_reason','Incorrect count discovered after submission'));
 denied:=false;begin perform public.crew_cash_save_checkout(other_tok,'cancel',jsonb_build_object('checkout_id',first,'reason','Another employee'));exception when insufficient_privilege then denied:=true;end;assert denied,'Self-cancel ownership unchanged';
 perform public.crew_cash_save_checkout(tok,'cancel',jsonb_build_object('checkout_id',first,'reason','Counting error; restart required'));
 select to_jsonb(c) into before_cancel from public.crew_cash_checkouts c where id=first;
 assert not exists(select 1 from crew_cash_ledger_entries where checkout_id=first),'No cancellation ledger';
 assert exists(select 1 from crew_cash_checkout_review_events where checkout_id=first and event='submitted' and (snapshot->>'counted_cash')::numeric=746),'Original submitted evidence retained';
 v:=public.crew_cash_mobile(tok,day);assert v#>>'{checkout,id}'=first::text and (v->>'can_restart_checkout')::boolean,'Cancelled card offers restart';
 v:=public.crew_cash_save_checkout(tok,'restart',jsonb_build_object('previous_checkout_id',first));second:=(v#>>'{checkout,id}')::uuid;
 assert first<>second and v#>>'{checkout,previous_checkout_id}'=first::text,'Independent linked attempt';
 assert (v#>>'{checkout,counted_cash}')::numeric=0 and v#>'{checkout,denomination_counts}'='{}'::jsonb and v#>>'{checkout,pos_expected_cash}' is null,'Fresh count; never copy cancelled evidence';
 v:=public.crew_cash_save_checkout(tok,'restart',jsonb_build_object('previous_checkout_id',first));assert v#>>'{checkout,id}'=second::text,'Retry returns same successor';
 denied:=false;begin perform public.crew_cash_save_checkout(other_tok,'restart',jsonb_build_object('previous_checkout_id',first));exception when others then denied:=true;end;assert denied,'Retry cannot transfer attempt ownership';
 denied:=false;begin insert into crew_cash_checkouts(outlet_id,business_date,checked_out_by_employee_id,floating_cash,expected_opening_cash,previous_checkout_id) values(outlet,day,emp,300,300,first);exception when others then denied:=true;end;assert denied,'Concurrent/direct duplicate excluded';
 perform public.crew_cash_save_checkout(tok,'cancel',jsonb_build_object('checkout_id',second,'reason','Second incomplete attempt cancelled'));
 v:=public.crew_cash_save_checkout(tok,'restart',jsonb_build_object('previous_checkout_id',second));third:=(v#>>'{checkout,id}')::uuid;
 assert third<>second and public.crew_cash_daily_checkout_id(outlet,day)=third,'Repeated restart uses latest leaf even with identical transaction timestamps';
 v:=public.crew_cash_save_checkout(tok,'restart',jsonb_build_object('previous_checkout_id',first));assert v#>>'{checkout,id}'=second::text,'Delayed retry never forks the chain';
 perform public.crew_cash_save_checkout(tok,'reconcile',jsonb_build_object('checkout_id',third,'denomination_counts','{"100":7,"10":4,"1":6}'::jsonb,'pos_expected_cash',750,'carry_forward',46));
 perform public.crew_cash_save_checkout(tok,'submit',jsonb_build_object('checkout_id',third,'variance_reason','Count checked and short by four ringgit'));
 assert not exists(select 1 from crew_cash_ledger_entries where outlet_id=outlet),'Submission posts no deposit';
 perform set_config('request.jwt.claim.sub',own::text,true);
 perform public.crew_cash_review_checkout(third,'reject','Recount before final approval');
 perform set_config('request.jwt.claim.sub','',true);
 perform public.crew_cash_save_checkout(tok,'reconcile',jsonb_build_object('checkout_id',third,'pos_expected_cash',746));
 perform public.crew_cash_save_checkout(tok,'submit',jsonb_build_object('checkout_id',third));
 assert (select review_required and review_status='pending' from crew_cash_checkouts where id=third),'Return/resubmit still requires Manager';
 perform set_config('request.jwt.claim.sub',own::text,true);
 perform public.crew_cash_review_checkout(third,'approve','Verified replacement allocation');
 assert (select counted_cash=746 and floating_cash=300 and carry_forward=46 and amount_for_deposit=400 and variance=0 and status='completed' from crew_cash_checkouts where id=third),'Canonical financial reconciliation';
 assert (select count(*)=1 and sum(signed_amount)=400 from crew_cash_ledger_entries where outlet_id=outlet),'Exactly one deposit movement';
 assert public.crew_cash_previous_carry(outlet,day+1)=46,'Next day uses effective completed attempt, not cancelled predecessor';
 assert (select to_jsonb(c)=before_cancel from crew_cash_checkouts c where id=first),'Original cancelled record remains immutable';
 assert jsonb_array_length(public.crew_cash_checkout_history(tok,day))=3,'Crew History retains every attempt';
 assert public.crew_cash_mobile(tok,day)#>>'{checkout,id}'=third::text,'Daily resolver selects completed effective attempt';
 denied:=false;begin perform public.crew_cash_save_checkout(tok,'cancel',jsonb_build_object('checkout_id',third,'reason','Forbidden after completion'));exception when invalid_parameter_value then denied:=true;end;assert denied,'Completed cancellation remains forbidden';
 denied:=false;begin perform public.crew_cash_save_checkout(tok,'restart',jsonb_build_object('previous_checkout_id',third));exception when others then denied:=true;end;assert denied,'Completed restart forbidden';
end;$$;
select 'Self-cancel/restart/retry/ownership/return/resubmit/approval/immutable evidence/deposit/carry/history checks passed' as result;
